#include <windows.h>

int main() {
  std::cout << "This program will terminate but stay resident." << std::endl;

  // Terminate the current thread
  ExitThread(0); 

  // This line will never be reached because the thread terminates immediately.
  std::cout << "This line will not be executed." << std::endl;

  return 0; // This line won't be reached either
}
```

